const MALUS_HORS_UE = /* MALUS_HORS_UE — config */ 4;

// --- Normalisation et détection -------------------------------------------

/** Minuscules, sans accents : la comparaison se fait sur cette forme. */
const norm = (s) =>
  String(s ?? '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');

const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/**
 * Cherche un terme entouré de non-alphanumériques, pour éviter qu'« ANSSI »
 * ne se déclenche à l'intérieur d'un autre mot. Les regex sont mémoïsées :
 * on teste ~150 termes contre chaque article.
 */
const RE_CACHE = new Map();
function contains(haystack, term) {
  let re = RE_CACHE.get(term);
  if (!re) {
    re = new RegExp(`(^|[^a-z0-9])${escapeRe(norm(term))}([^a-z0-9]|$)`);
    RE_CACHE.set(term, re);
  }
  return re.test(haystack);
}

// --- Traitement ------------------------------------------------------------

const retenus = [];
let ecartesExclusion = 0;
let ecartesScore = 0;

for (const item of $input.all()) {
  const article = item.json;

  // Item technique émis par la collecte quand aucun article n'est retenu :
  // il ne porte que le bilan des flux.
  if (article._empty || !article.title) continue;

  const titreNorm = norm(article.title);
  const texteNorm = norm(`${article.title} ${article.excerpt}`);

  if (EXCLUSIONS.some((t) => contains(texteNorm, t))) {
    ecartesExclusion += 1;
    continue;
  }

  let scoreTotal = 0;
  let signalFaible = false;
  const scoreParAxe = {};
  const themes = [];
  const motsCles = new Set();
  const explication = [];

  const ancreUE = MARQUEURS_UE.some((t) => contains(texteNorm, t));

  for (const [axe, cercles] of Object.entries(AXES)) {
    let scoreAxe = 0;

    for (const [cercle, termes] of Object.entries(cercles)) {
      for (const terme of termes) {
        if (!contains(texteNorm, terme)) continue;

        const dansTitre = contains(titreNorm, terme);
        const points = dansTitre ? POIDS[cercle] * BONUS_TITRE : POIDS[cercle];

        scoreAxe += points;
        motsCles.add(terme);
        explication.push(
          `${terme} (${LIBELLE_CERCLE[cercle]}${dansTitre ? `, titre ×${BONUS_TITRE}` : ''}) +${points}`,
        );
        if (cercle === 'signaux') signalFaible = true;
      }
    }

    // Sujet mondial revendiqué hors UE : on retire le bonus de titre qui
    // l'a fait monter, sans descendre sous zéro.
    if (scoreAxe > 0 && AXES_ANCRAGE_UE.has(axe) && !ancreUE) {
      const avant = scoreAxe;
      scoreAxe = Math.max(0, scoreAxe - MALUS_HORS_UE);
      explication.push(`hors périmètre UE −${avant - scoreAxe}`);
    }

    scoreParAxe[axe] = scoreAxe;
    if (scoreAxe >= SEUIL_AXE) themes.push(axe);
    scoreTotal += scoreAxe;
  }

  if (scoreTotal < SEUIL_MIN) {
    ecartesScore += 1;
    continue;
  }

  retenus.push({
    json: {
      ...article,
      score: scoreTotal,
      themes: themes.length ? themes : ['Transverse'],
      keywords: [...motsCles],
      weakSignal: signalFaible,
      scoreDetail: scoreParAxe,
      scoreExplain: explication,
    },
  });
}

// Les articles les plus pertinents en premier : utile à la lecture des
// exécutions et à l'ordre d'insertion en base.
retenus.sort((a, b) => b.json.score - a.json.score);

console.log(
  `Scoring : ${retenus.length} retenus · ${ecartesScore} sous le seuil (${SEUIL_MIN}) · ${ecartesExclusion} exclus`,
);

return retenus;

/**
 * PRÉPARATION DE L'INSERTION EN BASE
 *
 * Aplatit chaque article en colonnes prêtes pour la table `articles`.
 * Les tableaux (themes, keywords, score_explain) sont sérialisés au format
 * littéral Postgres, et score_detail en JSON : le nœud Postgres transmet
 * les valeurs telles quelles, c'est donc ici qu'on les met en forme.
 *
 * Le dédoublonnage est assuré par la contrainte UNIQUE sur dedup_key :
 * réinsérer un article connu ne crée pas de doublon et n'écrase pas le
 * statut de lecture (ON CONFLICT DO NOTHING côté requête).
 */

/**
 * Sérialise un tableau JS en littéral Postgres : {"a","b"}.
 * Les guillemets et antislashs internes sont échappés.
 */
function toPgArray(values) {
  const items = (values ?? [])
    .map((v) => String(v ?? '').trim())
    .filter(Boolean)
    .map((v) => `"${v.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`);
  return `{${items.join(',')}}`;
}

/** Postgres refuse les octets nuls, que certains flux mal encodés glissent. */
const clean = (s, max) => {
  const t = String(s ?? '').replace(/\0/g, '').trim();
  return max ? t.slice(0, max) : t;
};

return $input.all().map(({ json: article }) => ({
  json: {
    dedup_key:     clean(article.dedupKey, 500),
    title_vocab:   clean(article.titleVocab, 500),
    title:         clean(article.title, 1000),
    url:           clean(article.url, 2000),
    domain:        clean(article.domain, 255),
    source:        clean(article.source, 255),
    author:        clean(article.author, 255),
    feed:          clean(article.feed, 255),
    category:      clean(article.category, 100),
    source_type:   clean(article.sourceType, 100),
    excerpt:       clean(article.excerpt, 2000),
    published_at:  article.date,
    score:         Number(article.score) || 0,
    weak_signal:   Boolean(article.weakSignal),
    themes:        toPgArray(article.themes),
    keywords:      toPgArray(article.keywords),
    score_detail:  JSON.stringify(article.scoreDetail ?? {}),
    score_explain: toPgArray(article.scoreExplain),
  },
}));

/**
 * JOURNAL DE COLLECTE
 *
 * Reprend le bilan par flux produit lors de la collecte et l'aplatit pour
 * la table `feed_runs`. Sans cette trace, un flux mort depuis trois semaines
 * passe inaperçu : la vue v_sante_flux s'appuie dessus.
 *
 * Ce nœud lit la sortie du nœud « Collecte des flux » via la clé technique
 * `_feedReport`, portée par le premier item.
 */

const items = $('Collecte des flux').all();
const report = items[0]?.json?._feedReport ?? [];

if (!report.length) {
  // Aucun rapport : rien à journaliser, on ne fait pas échouer l'exécution.
  return [];
}

return report.map((entry) => ({
  json: {
    feed:        String(entry.feed ?? '').slice(0, 255),
    status:      entry.status === 'ok' ? 'ok' : 'échec',
    detail:      String(entry.detail ?? '').slice(0, 500),
    items_found: Number(entry.found) || 0,
    items_kept:  Number(entry.kept) || 0,
  },
}));

/**
 * MESSAGE DISCORD
 *
 * Construit l'embed envoyé au salon d'équipe pour les articles à score élevé.
 * Le nœud suivant se contente de POSTer `payload` sur le webhook.
 *
 * Contraintes Discord respectées ici : titre 256 car., description 4096,
 * valeur de champ 1024, footer 2048.
 */

const COULEURS = {
  signalFaible: 0x2ecc71, // vert : à surveiller
  tresEleve:    0xe74c3c, // rouge : à lire en priorité
  eleve:        0x3498db, // bleu : lecture normale
};

const SEUIL_TRES_ELEVE = /* SEUIL_URGENT — config */ 15;
const SEUIL_ALERTE = /* SEUIL_ALERTE — config */ 8;

/** Tronque en coupant proprement, sans laisser de mot à moitié. */
function tronquer(texte, max) {
  const s = String(texte ?? '');
  if (s.length <= max) return s;
  const coupe = s.slice(0, max - 1);
  const espace = coupe.lastIndexOf(' ');
  return `${espace > max * 0.6 ? coupe.slice(0, espace) : coupe}…`;
}

const dateFr = (iso) => {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '—';
  return d.toLocaleString('fr-FR', {
    timeZone: 'Europe/Paris',
    dateStyle: 'medium',
    timeStyle: 'short',
  });
};

return $input.all().map(({ json: article }) => {
  const niveau =
    article.score >= SEUIL_TRES_ELEVE ? 'très élevé' : article.score >= SEUIL_ALERTE ? 'élevé' : 'modéré';

  const couleur = article.weakSignal
    ? COULEURS.signalFaible
    : article.score >= SEUIL_TRES_ELEVE
      ? COULEURS.tresEleve
      : COULEURS.eleve;

  // Répartition du score entre les axes, axes à zéro omis.
  const repartition = Object.entries(article.scoreDetail ?? {})
    .filter(([, v]) => v > 0)
    .map(([axe, v]) => `**${axe}** : ${v}`)
    .join(' · ');

  const detail = tronquer(
    [repartition, (article.scoreExplain ?? []).join('\n')].filter(Boolean).join('\n'),
    1024,
  );

  return {
    json: {
      payload: {
        embeds: [
          {
            title: tronquer(article.title, 256),
            url: article.url,
            description: tronquer(article.excerpt, 300) || undefined,
            color: couleur,
            fields: [
              { name: '📅 Publication', value: dateFr(article.date), inline: true },
              { name: '✍️ Auteur', value: tronquer(article.author || article.source || '—', 100), inline: true },
              { name: '📰 Source', value: tronquer(article.source || '—', 100), inline: true },
              { name: `🎯 Score ${article.score} — ${niveau}`, value: detail || '—' },
            ],
            footer: {
              text: tronquer(
                `${(article.themes ?? []).join(' · ')}`
                + `${article.weakSignal ? ' · 🌱 signal faible' : ''}`
                + ' · barème : cœur 3 · périphérie 2 · signal 1 · ×2 si dans le titre',
                2048,
              ),
            },
            timestamp: article.date,
          },
        ],
      },
    },
  };
});
